/**
 * One typed client per contract. The clients in packages/ and the IDs in
 * packages/contract-ids.json are generated by the setup script: never edit them by hand.
 */
import idsJson from "@/packages/contract-ids.json";
import { Client as HelloWorldClient } from "@/packages/hello_world/dist/index.js";
import type { contract as sdk } from "@stellar/stellar-sdk";
import { stellar } from "@/lib/stellar";

/** Needed only for writes: the account that signs, and how to sign. See docs/stellar/contracts.md. */
export interface Signer {
  publicKey: string;
  signTransaction: sdk.SignTransaction;
}

type ContractIds = Partial<Record<string, Record<string, { id: string; alias: string }>>>;
const ids = idsJson as ContractIds;

function clientOptions(name: string, signer?: Signer) {
  const contractId = ids[stellar.network]?.[name]?.id;
  if (!contractId) {
    throw new Error(
      `No ${name} contract is deployed on ${stellar.network}. Run the setup script (npm run setup).`,
    );
  }
  if (!stellar.rpcUrl) {
    throw new Error("NEXT_PUBLIC_STELLAR_RPC_URL is not set. Add it to .env.");
  }
  return {
    contractId,
    networkPassphrase: stellar.networkPassphrase,
    rpcUrl: stellar.rpcUrl,
    allowHttp: stellar.network === "local",
    ...signer,
  };
}

export function helloWorld(signer?: Signer): HelloWorldClient {
  return new HelloWorldClient(clientOptions("hello_world", signer));
}
/** Network settings for this app, read from .env. Change the network there, not here. */

const PASSPHRASES = {
  testnet: "Test SDF Network ; September 2015",
  mainnet: "Public Global Stellar Network ; September 2015",
  local: "Standalone Network ; February 2017",
} as const;

export type StellarNetwork = keyof typeof PASSPHRASES;

function readNetwork(value: string | undefined): StellarNetwork {
  if (value !== undefined && Object.hasOwn(PASSPHRASES, value)) return value as StellarNetwork;
  throw new Error(
    `NEXT_PUBLIC_STELLAR_NETWORK is ${JSON.stringify(value)}. Set it in .env to one of: ${Object.keys(PASSPHRASES).join(", ")}. .env.example lists every key.`,
  );
}

// Next.js inlines NEXT_PUBLIC_ variables only when they are read by their full name.
const network = readNetwork(process.env.NEXT_PUBLIC_STELLAR_NETWORK);

export const stellar = {
  network,
  networkPassphrase: PASSPHRASES[network],
  rpcUrl: process.env.NEXT_PUBLIC_STELLAR_RPC_URL || undefined,
} as const;
