#![no_std]
use soroban_sdk::{
    contract, contracterror, contractimpl, contracttype, panic_with_error, token, Address, Env,
};

// About 30 days of ledgers (one ledger is roughly 5 seconds).
const TTL_THRESHOLD: u32 = 518_400;
const TTL_EXTEND_TO: u32 = 518_400;

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
#[repr(u32)]
pub enum StakingError {
    InvalidAmount = 1,
    InsufficientStake = 2,
}

#[contracttype]
pub enum DataKey {
    Token,
    Total,
    Staked(Address),
}

#[contract]
pub struct Staking;

fn token_address(env: &Env) -> Address {
    env.storage().instance().get(&DataKey::Token).unwrap()
}

fn total(env: &Env) -> i128 {
    env.storage().instance().get(&DataKey::Total).unwrap_or(0)
}

fn set_total(env: &Env, value: i128) {
    env.storage().instance().set(&DataKey::Total, &value);
}

fn staked_of(env: &Env, user: &Address) -> i128 {
    let key = DataKey::Staked(user.clone());
    env.storage().persistent().get(&key).unwrap_or(0)
}

fn set_staked(env: &Env, user: &Address, value: i128) {
    let key = DataKey::Staked(user.clone());
    if value == 0 {
        env.storage().persistent().remove(&key);
    } else {
        env.storage().persistent().set(&key, &value);
        env.storage()
            .persistent()
            .extend_ttl(&key, TTL_THRESHOLD, TTL_EXTEND_TO);
    }
}

#[contractimpl]
impl Staking {
    /// Runs once at deploy. `token` is the Stellar Asset Contract of the staked asset,
    /// for example the native XLM contract (`stellar contract id asset --asset native`).
    pub fn __constructor(env: Env, token: Address) {
        env.storage().instance().set(&DataKey::Token, &token);
        set_total(&env, 0);
        env.storage()
            .instance()
            .extend_ttl(TTL_THRESHOLD, TTL_EXTEND_TO);
    }

    /// Transfers `amount` from `user` to this contract and credits it to `user`.
    pub fn stake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, StakingError::InvalidAmount);
        }

        let this = env.current_contract_address();
        token::Client::new(&env, &token_address(&env)).transfer(&user, &this, &amount);

        set_staked(&env, &user, staked_of(&env, &user) + amount);
        set_total(&env, total(&env) + amount);
        env.storage()
            .instance()
            .extend_ttl(TTL_THRESHOLD, TTL_EXTEND_TO);
    }

    /// Debits `amount` from `user`'s stake and transfers it back to `user`.
    /// Fails if `user` has less than `amount` staked.
    pub fn unstake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, StakingError::InvalidAmount);
        }

        let current = staked_of(&env, &user);
        if amount > current {
            panic_with_error!(&env, StakingError::InsufficientStake);
        }

        set_staked(&env, &user, current - amount);
        set_total(&env, total(&env) - amount);

        let this = env.current_contract_address();
        token::Client::new(&env, &token_address(&env)).transfer(&this, &user, &amount);
        env.storage()
            .instance()
            .extend_ttl(TTL_THRESHOLD, TTL_EXTEND_TO);
    }

    /// The amount `user` has staked.
    pub fn staked(env: Env, user: Address) -> i128 {
        staked_of(&env, &user)
    }

    /// The amount staked by everyone.
    pub fn total_staked(env: Env) -> i128 {
        total(&env)
    }
}

mod test;
EOF
cat > contracts/contracts/staking/src/test.rs <<'EOF'
#![cfg(test)]
extern crate std;

use crate::{Staking, StakingClient, StakingError};
use soroban_sdk::{testutils::Address as _, token::StellarAssetClient, token::Client as TokenClient, Address, Env};

/// A fresh environment with a token (standing in for XLM's Stellar Asset Contract), the staking
/// contract deployed with that token, and a user holding 1_000 units of it.
fn setup() -> (Env, Address, Address, Address) {
    let env = Env::default();
    env.mock_all_auths();

    let admin = Address::generate(&env);
    let token = env.register_stellar_asset_contract_v2(admin).address();
    let contract_id = env.register(Staking, (token.clone(),));

    let user = Address::generate(&env);
    StellarAssetClient::new(&env, &token).mint(&user, &1_000);

    (env, contract_id, token, user)
}

#[test]
fn starts_empty() {
    let (env, contract_id, _token, user) = setup();
    let client = StakingClient::new(&env, &contract_id);
    assert_eq!(client.total_staked(), 0);
    assert_eq!(client.staked(&user), 0);
}

#[test]
fn stake_moves_tokens_and_records_amount() {
    let (env, contract_id, token, user) = setup();
    let client = StakingClient::new(&env, &contract_id);
    let tokens = TokenClient::new(&env, &token);

    client.stake(&user, &400);

    assert_eq!(client.staked(&user), 400);
    assert_eq!(client.total_staked(), 400);
    assert_eq!(tokens.balance(&user), 600);
    assert_eq!(tokens.balance(&contract_id), 400);
}

#[test]
fn stakes_accumulate_across_calls_and_users() {
    let (env, contract_id, token, user) = setup();
    let other = Address::generate(&env);
    StellarAssetClient::new(&env, &token).mint(&other, &500);
    let client = StakingClient::new(&env, &contract_id);

    client.stake(&user, &100);
    client.stake(&user, &250);
    client.stake(&other, &50);

    assert_eq!(client.staked(&user), 350);
    assert_eq!(client.staked(&other), 50);
    assert_eq!(client.total_staked(), 400);
}

#[test]
fn unstake_returns_tokens_and_reduces_stake() {
    let (env, contract_id, token, user) = setup();
    let client = StakingClient::new(&env, &contract_id);
    let tokens = TokenClient::new(&env, &token);

    client.stake(&user, &400);
    client.unstake(&user, &150);

    assert_eq!(client.staked(&user), 250);
    assert_eq!(client.total_staked(), 250);
    assert_eq!(tokens.balance(&user), 750);
    assert_eq!(tokens.balance(&contract_id), 250);
}

#[test]
fn unstaking_everything_leaves_zero() {
    let (env, contract_id, token, user) = setup();
    let client = StakingClient::new(&env, &contract_id);
    let tokens = TokenClient::new(&env, &token);

    client.stake(&user, &400);
    client.unstake(&user, &400);

    assert_eq!(client.staked(&user), 0);
    assert_eq!(client.total_staked(), 0);
    assert_eq!(tokens.balance(&user), 1_000);
}

#[test]
fn unstaking_more_than_staked_fails() {
    let (env, contract_id, token, user) = setup();
    let client = StakingClient::new(&env, &contract_id);
    let tokens = TokenClient::new(&env, &token);

    client.stake(&user, &400);

    let result = client.try_unstake(&user, &401);
    assert_eq!(result, Err(Ok(StakingError::InsufficientStake)));

    // A failed unstake changes nothing.
    assert_eq!(client.staked(&user), 400);
    assert_eq!(client.total_staked(), 400);
    assert_eq!(tokens.balance(&user), 600);
}

#[test]
fn unstaking_when_nothing_is_staked_fails() {
    let (env, contract_id, _token, user) = setup();
    let client = StakingClient::new(&env, &contract_id);

    let result = client.try_unstake(&user, &1);
    assert_eq!(result, Err(Ok(StakingError::InsufficientStake)));
}

#[test]
fn non_positive_amounts_are_rejected() {
    let (env, contract_id, _token, user) = setup();
    let client = StakingClient::new(&env, &contract_id);

    assert_eq!(client.try_stake(&user, &0), Err(Ok(StakingError::InvalidAmount)));
    assert_eq!(client.try_stake(&user, &-5), Err(Ok(StakingError::InvalidAmount)));
    assert_eq!(client.total_staked(), 0);
}
EOF
cd contracts && cargo test -p staking 2>&1 | tail -60

