input.command:
python3 - <<'EOF'
import re
p='lib/contracts.ts'
s=open(p).read()
s=s.replace('import { Client as HelloWorldClient } from "@/packages/hello_world/dist/index.js";\n',
 'import { Client as HelloWorldClient } from "@/packages/hello_world/dist/index.js";\nimport { Client as StakingClient } from "@/packages/staking/dist/index.js";\n',1)
s=s.rstrip('\n')+'''

export function stakingContract(signer?: Signer): StakingClient {
  return new StakingClient(clientOptions("staking", signer));
}
'''
open(p,'w').write(s)
EOF
mkdir -p app/staking && cat > app/staking/page.tsx <<'EOF'
import { connection } from "next/server";
import { Suspense } from "react";
import { stakingContract } from "@/lib/contracts";
import { stellar } from "@/lib/stellar";

type SearchParams = Promise<{ [key: string]: string | string[] | undefined }>;

function describe(error: unknown): string {
  // Some network errors arrive with an empty message; fall back to their text.
  return (error instanceof Error && error.message) || String(error) || "unknown error";
}

async function TotalStaked() {
  // Read the chain when a request arrives, not while `next build` prerenders the page.
  await connection();
  try {
    const { result } = await stakingContract().total_staked();
    return (
      <p>
        Total staked: <span data-testid="total-staked">{result.toString()}</span>
      </p>
    );
  } catch (error) {
    return (
      <p data-testid="total-error">
        Could not read the total: {describe(error)} (RPC: {stellar.rpcUrl ?? "not set"})
      </p>
    );
  }
}

async function AccountStaked({ searchParams }: { searchParams: SearchParams }) {
  await connection();
  const { address } = await searchParams;
  const user = Array.isArray(address) ? address[0] : address;
  if (!user) {
    return (
      <p>
        Add <code>?address=G…</code> to the URL to see one account&apos;s stake.
      </p>
    );
  }
  try {
    const { result } = await stakingContract().staked({ user });
    return (
      <p>
        Staked by <code>{user}</code>: <span data-testid="staked-amount">{result.toString()}</span>
      </p>
    );
  } catch (error) {
    return (
      <p data-testid="staked-error">
        Could not read the stake for <code>{user}</code>: {describe(error)}
      </p>
    );
  }
}

export default function StakingPage({ searchParams }: { searchParams: SearchParams }) {
  return (
    <main>
      <h1>Staking</h1>
      <p>
        Network: <code>{stellar.network}</code>
      </p>
      <Suspense fallback={<p>Reading the total…</p>}>
        <TotalStaked />
      </Suspense>
      <Suspense fallback={<p>Reading the stake…</p>}>
        <AccountStaked searchParams={searchParams} />
      </Suspense>
    </main>
  );
}
EOF
npm run check 2>&1 | tail -80

